 1  import { FocusEvent } from 'react';
 2  import { InputBaseComponentProps } from '@mui/material';
 3  
 4  // "90m", "1.5h" or "1h30" -> "1h 30m"; anything else is left as typed.
 5  export function normaliseDuration(text: string): string {
 6    const trimmed = text.trim().toLowerCase();
 7    const hours = trimmed.match(/^(\d+(?:\.\d+)?)\s*h$/);
 8    const minutes = trimmed.match(/^(\d+)\s*m$/);
 9    const both = trimmed.match(/^(\d+)\s*h\s*(\d+)\s*m?$/);
10    let total: number | null = null;
11    if (hours) total = Math.round(Number(hours[1]) * 60);
12    else if (minutes) total = Number(minutes[1]);
13    else if (both) total = Number(both[1]) * 60 + Number(both[2]);
14    if (total === null) return text;
15    const h = Math.floor(total / 60);
16    const m = total % 60;
17    return [h ? `${h}h` : '', m ? `${m}m` : ''].filter(Boolean).join(' ') || '0m';
18  }
19  
20  // An input that tidies the duration when the user leaves the field.
21  export function DurationInput(props: InputBaseComponentProps) {
22    const { inputRef, onBlur, ...other } = props;
23    return (
24      <input
25        {...other}
26        ref={inputRef}
27        onBlur={(event: FocusEvent<HTMLInputElement>) => {
28          event.target.value = normaliseDuration(event.target.value);
29          onBlur?.(event);
30        }}
31      />
32    );
33  }

**TextField › Forward ref instead of inputRef prop**

Change ref forwarding expectations on custom `inputComponent`.

The component should forward the `ref` prop instead of the `inputRef` prop.

```diff
-function NumberFormatCustom(props) {
-  const { inputRef, onChange, ...other } = props;
+const NumberFormatCustom = React.forwardRef(function NumberFormatCustom(
+  props,
+  ref,
+) {
  const { onChange, ...other } = props;

  return (
    <NumberFormat
      {...other}
-     getInputRef={inputRef}
+     getInputRef={ref}
```

---

**ref › Refactor non-ref-forwarding class components**

Support for non-ref-forwarding class components in the `component` prop or as immediate `children` has been dropped.

If you were using `unstable_createStrictModeTheme` or didn't see any warnings related to `findDOMNode` in `React.StrictMode` then you don't need to take any further action.

Otherwise check out the [Caveat with refs](https://v5.mui.com/material-ui/guides/composition/#caveat-with-refs) section in the Composition guide to find out how to migrate.
This change affects almost all components where you're using the `component` prop or passing `children` to components that require `children` to be elements (for example `<MenuList><CustomMenuItem /></MenuList>`).

---

**TablePagination › Move custom class on input to select**

Move the custom class on `input` to `select`.

The `input` key is applied on another element.

```diff
  <TablePagination
-  classes={{ input: 'foo' }}
+  classes={{ select: 'foo' }}
  />
```

